-- ------------------------------------------------------------
--  마스터 FK 연결
-- ------------------------------------------------------------
update legacy_settlements l set retailer_id = r.id
  from retailers r where r.code = l.retailer_code and l.retailer_id is null;
update legacy_settlements l set workshop_id = w.id
  from workshops w where w.code = l.workshop_code and l.workshop_id is null;

-- ------------------------------------------------------------
--  실제 정산유형 코드로 교정
--   · One Care : 033 으로 만들었으면 이미 일치(0행)
--   · Recall   : 기존 'Recall Upselling Program' 유형 코드로 바꿔 붙인다
-- ------------------------------------------------------------
update legacy_settlements l set type_code = t.code
  from settlement_types t
 where l.item in ('ONECARE_SVC','ONECARE_SR') and l.type_code <> t.code
   and (t.code = 'ONE_CARE_INCENTIVE' or t.name ilike '%one care%incentive%');
update legacy_settlements l set type_code = t.code
  from settlement_types t
 where l.item = 'RECALL' and l.type_code <> t.code
   and (t.code ilike '%recall%' or t.name ilike '%recall%');

-- 연결 결과
select l.type_code, t.name, l.item, count(*) as rows, sum(l.amount) as 누적
  from legacy_settlements l
  left join settlement_types t on t.code = l.type_code
 where l.item in ('ONECARE_SVC','ONECARE_SR','RECALL')
 group by l.type_code, t.name, l.item
 order by l.type_code, l.item;

-- ------------------------------------------------------------
--  검증 — 기대값
--    ONECARE_SVC   94행  100,600,000
--    ONECARE_SR    44행   15,200,000
--    RECALL        41행  167,971,662
--    legacy_settlements 총 1,019행 (기존 840 + 179)
-- ------------------------------------------------------------
select period_key, period_label,
       sum(case when item='ONECARE_SVC' then amount end) as OneCare_SVC,
       sum(case when item='ONECARE_SR'  then amount end) as OneCare_SR,
       sum(case when item='RECALL'      then amount end) as Recall,
       count(*) as rows
from legacy_settlements
where item in ('ONECARE_SVC','ONECARE_SR','RECALL')
group by period_key, period_label
order by period_key;

select count(*) as 총행수 from legacy_settlements;
